mapper.select:
SELECT COALESCE(MAX(revision_no),0)
FROM vi_training_policy_revision
WHERE policy_id=#{id}

mapper.update:
UPDATE vi_training_policy
SET draft_revision_id=#{draftRevisionId},version=version+1,updated_at=UTC_TIMESTAMP(3)
WHERE id=#{id} AND version=#{version}

mapper.select:
SELECT *
FROM vi_training_plan_snapshot
WHERE application_id=#{application} AND company_revision=#{epoch}

SELECT *
FROM vi_training_run
WHERE plan_snapshot_id=#{plan} AND material_revision=#{material}

SELECT *
FROM vi_training_attempt
WHERE application_id=#{application}
    AND (course_key=#{key} OR (course_key IS NULL AND training_id IN (
        SELECT id
        FROM vi_training_course
        WHERE course_key=#{key}
    )))
ORDER BY attempt_no DESC,id DESC
LIMIT 1

SELECT COUNT(*)
FROM vi_training_attempt
WHERE application_id=#{application}
    AND (course_key=#{key} OR (course_key IS NULL AND training_id IN (
        SELECT id
        FROM vi_training_course
        WHERE course_key=#{key}
    )))

SELECT COALESCE(MAX(attempt_no),0)
FROM vi_training_attempt
WHERE application_id=#{application}
    AND (course_key=#{key} OR (course_key IS NULL AND training_id IN (
        SELECT id
        FROM vi_training_course
        WHERE course_key=#{key}
    )))
